import { chromium } from "playwright-core";
const b = await chromium.launch({ channel: "chrome" });
const c = await b.newContext({ viewport:{width:390,height:844}, hasTouch:true, isMobile:true, deviceScaleFactor:2, extraHTTPHeaders:{"x-flare-test":"1"} });
const p = await c.newPage();
await p.goto("https://flare-outside.onrender.com", {waitUntil:"networkidle", timeout:90000});
await p.screenshot({path:"home-fold.png"});
await p.screenshot({path:"home-full.png", fullPage:true});
console.log(await p.evaluate(()=>document.body.innerText));
console.log([...document?[]:[]]);
const links = await p.$$eval("a", as=>as.map(a=>a.innerText.trim()+" -> "+a.href));
console.log(links.join("\n"));
await b.close();
EOF
NODE_PATH="<project>/flare/node_modules" node s1.mjs 2>&1 | head -150

